import{_ as s,o as e,c as n,a2 as t}from"./chunks/framework.doxMM-x8.js";const h=JSON.parse('{"title":"项目结构","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/architecture/project-structure","contentType":"concept","prev":false,"next":{"text":"模块边界","link":"/architecture/module-boundaries"}},"headers":[],"relativePath":"architecture/project-structure.md","filePath":"architecture/project-structure.md"}'),p={name:"architecture/project-structure.md"};function r(c,a,l,i,o,d){return e(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="项目结构" tabindex="-1">项目结构 <a class="header-anchor" href="#项目结构" aria-label="Permalink to &quot;项目结构&quot;">​</a></h1><p>修改 Lab Word 前，先区分实际应用、共享能力和隔离预览。Lab Viewer 与会话资产库已接入；Foundation V1 的持久世界和后端设备程序按已发布实施票继续开发。</p><h2 id="源码地图" tabindex="-1">源码地图 <a class="header-anchor" href="#源码地图" aria-label="Permalink to &quot;源码地图&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apps/</span></span>
<span class="line"><span>  web/src/app-examples.tsx  业务贡献的显式组装点</span></span>
<span class="line"><span>  web/src/router.tsx        Web 路由适配</span></span>
<span class="line"><span>  api/src/lib.rs            HTTP Router 与 OpenAPI 组合</span></span>
<span class="line"><span>  worker/src/main.rs        后台 Handler 与维护任务</span></span>
<span class="line"><span>  desktop/src/              Electron 宿主与 IPC</span></span>
<span class="line"><span>  docs/.vitepress/           双语文档站</span></span>
<span class="line"><span>crates/</span></span>
<span class="line"><span>  app/src/modules/          身份、成员、任务、文件、知识库等</span></span>
<span class="line"><span>  platform/src/             数据库、存储、邮件、缓存与观测</span></span>
<span class="line"><span>packages/</span></span>
<span class="line"><span>  views/src/lab/             正式查看器、会话资产库与 Lab 业务贡献</span></span>
<span class="line"><span>  views/src/shell/           通用应用壳与组装合同</span></span>
<span class="line"><span>  views/src/knowledge/       知识库界面</span></span>
<span class="line"><span>  ui/src/                   共享组件与样式</span></span>
<span class="line"><span>  contracts/                Rust 生成的 API 合同</span></span>
<span class="line"><span>  sdk/                      生成客户端</span></span>
<span class="line"><span>migrations/                 显式 SQL 迁移</span></span>
<span class="line"><span>scripts/                    开发、检查、构建与运维</span></span>
<span class="line"><span>docs/                       正文、领域词汇入口、ADR 与计划</span></span></code></pre></div><p>正式查看器的用法见<a href="./../guides/lab-viewer">指南</a>。下一阶段已接受的 Foundation v1 预览保存在独立的 <code>preview/lab-foundation-v1</code> 分支中，取得和运行方式见<a href="https://github.com/CaiZongyuan/labworld/blob/c6c3063719c76d24cbdb1b03dd9bb4a724e445a9/docs/handoffs/digital-twin-foundation-v1.md" target="_blank" rel="noreferrer">开发交接</a>；它不属于正式应用构建。</p><h2 id="lab-接入点" tabindex="-1">Lab 接入点 <a class="header-anchor" href="#lab-接入点" aria-label="Permalink to &quot;Lab 接入点&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/labworld/blob/c6c3063719c76d24cbdb1b03dd9bb4a724e445a9/apps/web/src/app-examples.tsx" target="_blank" rel="noreferrer">显式组装点</a>消费业务贡献，<a href="https://github.com/CaiZongyuan/labworld/blob/c6c3063719c76d24cbdb1b03dd9bb4a724e445a9/apps/web/src/router.tsx" target="_blank" rel="noreferrer">路由适配</a>将页面接入宿主。贡献合同定义在 <a href="https://github.com/CaiZongyuan/labworld/blob/c6c3063719c76d24cbdb1b03dd9bb4a724e445a9/packages/views/src/shell/app-contract.ts" target="_blank" rel="noreferrer">app-contract.ts</a>，组装检查由 <a href="https://github.com/CaiZongyuan/labworld/blob/c6c3063719c76d24cbdb1b03dd9bb4a724e445a9/packages/views/src/shell/app-contract.ts" target="_blank" rel="noreferrer">app-contract.ts</a>负责。</p><p>Lab 的模型导入、三维视口与资产信息属于自己的业务界面。通用壳不认识设备。Lab 贡献已注册 <code>/lab</code> 和 <code>/assets</code>，登录后默认进入 Lab；直接访问 <code>/</code> 保持通用首页。既有页面与三维代码按需加载，Foundation 扩展应保持这些接入职责。</p><h2 id="检查边界" tabindex="-1">检查边界 <a class="header-anchor" href="#检查边界" aria-label="Permalink to &quot;检查边界&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boundaries:check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> typecheck</span></span></code></pre></div><p>从仓库根目录运行。边界检查核对包依赖、Rust 模块表所有权与纯 Domain 的基础设施导入；它没有提供完整的示例增删工具。源码、行为和权限的检查职责见<a href="./../testing/feedback-loop">开发与验证</a>。</p><p>下一步阅读<a href="./module-boundaries">模块边界</a>，再按已验收的 Lab 体验实施。</p><hr><p>源码版本：<code>c6c3063719c7</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/c6c3063719c76d24cbdb1b03dd9bb4a724e445a9/docs/architecture/project-structure.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,14)])])}const u=s(p,[["render",r]]);export{h as __pageData,u as default};
